<script setup lang="ts">
import { ref, onMounted, computed } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import FieldControl from '../components/FieldControl.vue'
import EvidencePanel from '../components/EvidencePanel.vue'
import ExchangePanel from '../components/ExchangePanel.vue'
import { api, type Row, quantity, money, statusText } from '../services/api'
const props = defineProps<{ user: Row }>()
const rows = ref<Row[]>([]), total = ref(0), page = ref(1), query = ref(''), selected = ref<Row[]>([]), detail = ref<Row | null>(null), dialog = ref(false), loading = ref(false), form = ref<Row>({}), editing = ref<Row | null>(null), operations = ref<Row[]>([]), errors = ref<Row>({}), history = ref<Row | null>(null), quote = ref<Row | null>(null), selections = ref<Row>({}), selectionBasis = ref<Row>({}), formRef = ref(), showDeleted = ref(false)
const operation = computed(() => operations.value.find(x => x.id === form.value.operation_id))
const locationReference = computed(() => operation.value?.work_target_type === 'physical' ? 'physical' : 'towers')
async function load() { const result = await api(`/demands?page=${page.value}&q=${encodeURIComponent(query.value)}&deleted=${showDeleted.value}`); rows.value = result.items; total.value = result.total; if (detail.value) detail.value = await api('/demands/' + detail.value.id) }
async function edit(row?: Row) { editing.value = row || null; const value = row ? await api('/demands/' + row.id) : null; form.value = value ? structuredClone(value) : { demand_no: '', operation_id: '', problem_description: '', completion_standard: '', work_locations: [], materials: [], sources: [{ description: '', discovered_on: '', source_system: 'manual' }] }; for (const loc of form.value.work_locations) loc.site_features_json = JSON.stringify(loc.site_features_json || {}); errors.value = {}; dialog.value = true }
function chooseOperation() { const op = operation.value; if (!op) return; form.value.completion_standard ||= op.completion_standard; form.value.target_object = op.default_target_object; if (!form.value.work_locations.length) addLocation() }
function addLocation() { const op = operation.value; form.value.work_locations.push({ location_kind: op?.work_target_type === 'physical' ? 'physical_tower' : op?.default_location_kind === 'span' ? 'span' : 'logical_tower', quantity_scaled: op?.default_quantity_scaled || 10000, work_mode: 'unspecified', site_features_json: '{}' }) }
async function save() { if (!await formRef.value?.validate().catch(() => false)) return; loading.value = true; try { const input = { ...form.value, expected_version: editing.value?.current_version, sources: form.value.sources.filter((x: Row) => x.id || x.description) }; await api('/demands' + (editing.value ? '/' + editing.value.id : ''), 'POST', input); dialog.value = false; await load(); ElMessage.success('需求版本已保存') } catch (e) { errors.value = (e as Row).fields || {}; ElMessage.error((e as Error).message) } finally { loading.value = false } }
async function transition(row: Row, status: string) { try { await ElMessageBox.confirm('确认记录此次正式需求状态决定？', statusText[status]); const timeline = await api('/demands/' + row.id + '/history'); await api('/demands/' + row.id + '/status', 'POST', { status, expected_version: row.current_version, expected_event_seq: timeline.events.at(-1).event_seq }); await load() } catch (e) { if (e instanceof Error) ElMessage.error(e.message) } }
async function calculatePrice(confirm = false) { if (!detail.value) return; try { quote.value = await api(`/demands/${detail.value.id}/quote`, 'POST', { expected_version: detail.value.current_version, confirm, selections: selections.value, selection_basis: selectionBasis.value }); if (confirm) ElMessage.success('已保存正式参考报价') } catch (e) { ElMessage.error((e as Error).message) } }
async function showHistory() { history.value = await api('/demands/' + detail.value!.id + '/history') }
async function remove(row: Row) { try { await ElMessageBox.confirm('删除后从正常列表移除，正式历史继续可查。须先取消需求并解除当前关联。', '删除需求'); await api('/demands/' + row.id, 'DELETE', { expected_version: row.current_version }); detail.value = null; await load() } catch (e) { if (e instanceof Error) ElMessage.error(e.message) } }
onMounted(async () => { operations.value = (await api('/catalog/operations?page_size=200')).items; await load() })
</script>
<template>
  <template v-if="!detail"><div class="page-heading"><div><div class="section-caption">Professional demands</div><h1>专业需求</h1><p>一种操作，多处作业位置。数量、现场条件与来源分别留存。</p></div><div><ExchangePanel kind="demands" :selected-ids="selected.map(x => x.id)" :query="query" @changed="load" /><ElButton type="primary" @click="edit()">新增需求</ElButton></div></div>
  <div class="panel"><div class="toolbar"><ElInput v-model="query" placeholder="需求编号、问题或位置" clearable @change="load" /><ElCheckbox v-model="showDeleted" @change="load">包含已删除</ElCheckbox><ElButton @click="load">刷新</ElButton></div><ElTable :data="rows" @selection-change="selected = $event"><ElTableColumn type="selection" width="42" /><ElTableColumn prop="demand_no" label="需求编号" width="140" sortable /><ElTableColumn prop="operation_snapshot" label="操作类型" min-width="150" /><ElTableColumn prop="problem_description" label="问题描述" min-width="200" /><ElTableColumn label="数量 / 位置" width="130"><template #default="{ row }">{{ quantity(row.quantity_scaled) }} {{ row.unit_snapshot }}<div class="muted">{{ row.work_locations.length }} 处位置</div></template></ElTableColumn><ElTableColumn label="状态" width="100"><template #default="{ row }"><ElTag>{{ row.deleted ? '已删除' : statusText[row.status] }}</ElTag></template></ElTableColumn><ElTableColumn label="当前关联" min-width="100"><template #default="{ row }">{{ row.binding ? '已关联子项目' : '未关联' }}</template></ElTableColumn><ElTableColumn label="操作" width="100"><template #default="{ row }"><ElButton size="small" @click="detail = row">查看</ElButton></template></ElTableColumn></ElTable><ElPagination v-model:current-page="page" :total="total" :page-size="30" layout="prev, pager, next, total" @current-change="load" /></div></template>
  <template v-else><div class="detail-header"><ElButton @click="detail = null">返回需求列表</ElButton><h1>{{ detail.demand_no }} · {{ detail.operation_snapshot }}</h1><ElTag>{{ statusText[detail.status] }} · V{{ detail.current_version }}</ElTag></div><div class="toolbar"><ElButton @click="edit(detail)">修订需求</ElButton><ElButton @click="showHistory()">完整历史</ElButton><ElButton @click="calculatePrice()">参考价试算</ElButton><ElButton v-if="['admin','verifier'].includes(user.role) && detail.status !== 'active' && detail.status !== 'cancelled'" type="primary" @click="transition(detail, 'active')">确认有效</ElButton><ElButton v-if="detail.status === 'active'" @click="transition(detail, 'returned')">退回</ElButton><ElButton v-if="detail.status !== 'cancelled'" type="danger" plain @click="transition(detail, 'cancelled')">取消需求</ElButton><ElButton type="danger" @click="remove(detail)">删除</ElButton></div>
  <div class="panel"><h2>需求定义</h2><ElDescriptions :column="2" border><ElDescriptionsItem label="问题描述">{{ detail.problem_description }}</ElDescriptionsItem><ElDescriptionsItem label="总工作量">{{ quantity(detail.quantity_scaled) }} {{ detail.unit_snapshot }}</ElDescriptionsItem><ElDescriptionsItem label="作业对象">{{ detail.work_object_snapshot }}</ElDescriptionsItem><ElDescriptionsItem label="验收标准">{{ detail.completion_standard }}</ElDescriptionsItem></ElDescriptions></div><div class="panel"><h2>作业位置</h2><ElTable :data="detail.work_locations"><ElTableColumn label="位置" min-width="180"><template #default="{ row }">{{ row.location_snapshot_json.line_name }} {{ row.location_snapshot_json.tower_no || row.location_snapshot_json.physical_code || row.span_id }}</template></ElTableColumn><ElTableColumn label="数量" width="130"><template #default="{ row }">{{ quantity(row.quantity_scaled) }}</template></ElTableColumn><ElTableColumn prop="work_mode" label="作业方式" /><ElTableColumn label="现场特征"><template #default="{ row }">{{ JSON.stringify(row.site_features_json) }}</template></ElTableColumn></ElTable></div><div class="panel"><h2>来源与预计物资</h2><p v-for="source in detail.sources" :key="source.id">{{ source.description }} <span class="muted">{{ source.discovered_on }}</span></p><ElTable :data="detail.materials"><ElTableColumn prop="material_id" label="物资标识" /><ElTableColumn label="预计数量"><template #default="{ row }">{{ quantity(row.quantity_scaled) }} {{ row.unit_snapshot }}</template></ElTableColumn></ElTable></div><EvidencePanel :key="detail.id" owner-kind="demand_id" :owner-id="detail.id" /></template>
  <ElDialog v-model="dialog" :title="editing ? '修订需求' : '新增专业需求'" width="1000px" :close-on-click-modal="false"><ElForm ref="formRef" :model="form" label-position="top" novalidate><div class="form-grid"><ElFormItem label="需求编号" prop="demand_no" :rules="[{required:true,message:'请填写需求编号'}]"><ElInput v-model="form.demand_no" :disabled="!!editing" /></ElFormItem><ElFormItem label="操作类型" prop="operation_id" :rules="[{required:true,message:'请选择操作类型'}]"><ElSelect v-model="form.operation_id" filterable @change="chooseOperation"><ElOption v-for="op in operations" :key="op.id" :value="op.id" :label="op.name" /></ElSelect></ElFormItem><ElFormItem label="问题描述" prop="problem_description" :rules="[{required:true,message:'请填写问题描述'}]"><ElInput v-model="form.problem_description" type="textarea" /></ElFormItem><ElFormItem label="验收标准" prop="completion_standard" :rules="[{required:true,message:'请填写验收标准'}]"><ElInput v-model="form.completion_standard" type="textarea" /></ElFormItem></div><h3 class="subheading">作业位置与工作量</h3><ElAlert v-if="operation" :title="'作业对象和单位由操作定义自动取得。' + (operation.entry_hint || '')" type="info" :closable="false" /><div v-for="(loc,index) in form.work_locations" :key="index" class="panel"><div class="form-grid"><ElFormItem v-if="operation?.allow_span && operation?.allow_tower" label="位置类型"><ElSelect v-model="loc.location_kind"><ElOption label="杆塔" value="logical_tower" /><ElOption label="档距" value="span" /></ElSelect></ElFormItem><ElFormItem label="作业设备" required><FieldControl v-model="loc[loc.location_kind === 'span' ? 'span_id' : loc.location_kind === 'physical_tower' ? 'physical_tower_id' : 'logical_tower_id']" :field="{type:'ref',reference:loc.location_kind === 'span' ? 'spans' : locationReference}" /></ElFormItem><ElFormItem label="实际数量" required><FieldControl v-model="loc.quantity_scaled" :field="{type:'quantity'}" /></ElFormItem><ElFormItem label="作业方式"><ElSelect v-model="loc.work_mode"><ElOption label="未明确" value="unspecified" /><ElOption label="停电" value="outage" /><ElOption label="不停电" value="non_outage" /></ElSelect></ElFormItem><ElFormItem label="现场价格特征（按需填写）"><ElInput v-model="loc.site_features_json" type="textarea" /></ElFormItem></div><ElButton type="danger" plain @click="form.work_locations.splice(index,1)">移除此位置</ElButton></div><ElButton :disabled="!operation" @click="addLocation">添加位置</ElButton><h3 class="subheading">预计物资（可不填）</h3><div v-for="(item,index) in form.materials" :key="index" class="toolbar"><FieldControl v-model="item.material_id" :field="{type:'ref',reference:'materials'}" /><FieldControl v-model="item.quantity_scaled" :field="{type:'quantity'}" /><ElButton type="danger" @click="form.materials.splice(index,1)">移除</ElButton></div><ElButton @click="form.materials.push({quantity_scaled:10000})">添加预计物资</ElButton><h3 class="subheading">来源依据</h3><div v-for="(source,index) in form.sources" :key="index" class="form-grid"><ElFormItem label="来源说明"><ElInput v-model="source.description" :disabled="!!source.id" /></ElFormItem><ElFormItem label="发现日期"><ElDatePicker v-model="source.discovered_on" value-format="YYYY-MM-DD" :disabled="!!source.id" /></ElFormItem></div><ElButton @click="form.sources.push({description:'',source_system:'manual'})">补充来源</ElButton></ElForm><template #footer><ElButton @click="dialog = false">取消</ElButton><ElButton type="primary" :loading="loading" @click="save">保存需求版本</ElButton></template></ElDialog>
  <ElDialog :model-value="!!quote" title="参考价格" width="850px" @close="quote = null"><template v-if="quote"><ElAlert :title="quote.complete ? '完整参考价 ¥' + money(quote.total_fen) : '未完整计价，已计价小计 ¥' + money(quote.subtotal_fen)" :type="quote.complete ? 'success' : 'warning'" :closable="false" /><ElTable :data="quote.lines"><ElTableColumn prop="location_item_no" label="位置序号" /><ElTableColumn label="金额"><template #default="{row}">¥{{ money(row.amount_fen) }}</template></ElTableColumn></ElTable><div v-for="missing in quote.missing" :key="missing.location_item_no" class="panel"><p>位置 {{ missing.location_item_no }} · {{ missing.reason }}</p><ElSelect v-model="selections[missing.location_item_no]"><ElOption v-for="candidate in missing.candidates" :key="candidate.id" :value="candidate.id" :label="candidate.title" /></ElSelect><ElInput v-model="selectionBasis[missing.location_item_no]" placeholder="选择依据" /></div><ElButton @click="calculatePrice()">重新试算</ElButton><ElButton type="primary" :disabled="!quote.complete" @click="calculatePrice(true)">确认正式报价</ElButton><ElButton @click="quote=null">关闭报价</ElButton></template></ElDialog>
  <ElDialog :model-value="!!history" title="需求完整历史" width="900px" @close="history = null"><pre class="data-json">{{ JSON.stringify(history,null,2) }}</pre></ElDialog>
</template>
